const root = $input.first()?.json || {};
const items = Array.isArray(root.items) ? root.items : [];
const batch = items.find(x => x.status === "uploaded");

if (!batch) return [];

return [{
  json: {
    batch_id: batch.id,
    file_extension: String(batch.file_extension || "").toLowerCase(),
    folder_name: batch.folder_name,
    original_filename: batch.original_filename
  }
}];

const result = $input.first()?.json || {};

if (result.claimed !== true || !result.item) {
  return [];
}

const b = result.item;

return [{
  json: {
    batch_id: b.id,
    worker_token: b.worker_token,
    file_extension: String(b.file_extension || "").toLowerCase(),
    folder_name: b.folder_name,
    original_filename: b.original_filename
  }
}];

const root = $input.first()?.json || {};

if (!root.ok || !Array.isArray(root.pages)) {
  throw new Error("OCR не вернул корректный массив pages");
}

const batchId = $("Claim and normalize").first().json.batch_id;

const schema = {
  type: "object",
  additionalProperties: false,
  properties: {
    records: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: false,
        properties: {
          company_name: {type: ["string", "null"]},
          inn: {type: ["string", "null"]},
          city: {type: ["string", "null"]},
          full_name: {type: ["string", "null"]},
          position: {type: ["string", "null"]},
          email: {type: ["string", "null"]},
          phone: {type: ["string", "null"]},
          emails: {type: "array", items: {type: "string"}},
          phones: {type: "array", items: {type: "string"}},
          revenue_rub: {type: ["number", "null"]},
          revenue_year: {type: ["integer", "null"]},
          source_row: {type: ["integer", "null"]},
          warnings: {type: "array", items: {type: "string"}}
        },
        required: [
          "company_name", "inn", "city", "full_name", "position",
          "email", "phone", "emails", "phones", "revenue_rub",
          "revenue_year", "source_row", "warnings"
        ]
      }
    }
  },
  required: ["records"]
};

const systemPrompt =
  "Ты извлекаешь сведения об инвесторах и компаниях из русскоязычных документов. " +
  "Извлеки ВСЕ отдельные компании и контакты, которые явно указаны на странице. " +
  "Не объединяй разные компании. Не выдумывай ИНН, телефоны, email, город или выручку. " +
  "Сохраняй все найденные email и телефоны в массивах. " +
  "ИНН — только 10 или 12 цифр, если он полностью читается. " +
  "Выручку записывай числом в рублях только если сумма и единицы однозначны. " +
  "При неоднозначности оставляй null и добавляй предупреждение. " +
  "Не включай заголовки и рекламные фрагменты. Строго соблюдай JSON Schema.";

const result = root.pages.map((p, i) => {
  const page = {
    batch_id: batchId,
    pages_total: root.pages.length,
    source_page: Number(p.page) || i + 1,
    page_text: String(p.raw_text || ""),
    needs_review: Boolean(p.needs_review),
    ocr_error: p.ocr_error || null
  };

  return {
    json: {
      ...page,
      ollama_request: {
        model: "qwen2.5:7b",
        stream: false,
        format: schema,
        options: {
          temperature: 0,
          num_ctx: 16384,
          num_predict: 6000
        },
        messages: [
          {role: "system", content: systemPrompt},
          {
            role: "user",
            content:
              "Извлеки все записи инвесторов и компаний с этой страницы. " +
              "Не объединяй разные контакты. Сохраняй порядок появления. " +
              "Текст страницы с номером: " +
              String(page.source_page) + "\n" + page.page_text
          }
        ]
      }
    }
  };
});

if (!result.length) {
  throw new Error("В PDF нет страниц");
}

if (result.every(x => !x.json.page_text.trim())) {
  throw new Error("OCR не извлёк текст ни с одной страницы");
}

return result;

const outputs = $input.all();
const pages = $("Prepare PDF pages").all();

if (outputs.length !== pages.length) {
  throw new Error(
    "Не все страницы обработаны Ollama: " +
    outputs.length + " из " + pages.length
  );
}

function normalizeRevenue(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  let s = String(value)
    .replace(/\u00a0/g, " ")
    .replace(/руб\.?|₽/gi, "")
    .replace(/\s/g, "")
    .trim();

  if (s.includes(",") && s.includes(".")) {
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) {
      s = s.replace(/\./g, "").replace(",", ".");
    } else {
      s = s.replace(/,/g, "");
    }
  } else if (s.includes(",")) {
    const parts = s.split(",");
    s = parts.length === 2 && parts[1].length !== 3
      ? s.replace(",", ".")
      : s.replace(/,/g, "");
  }

  const n = Number(s);
  return Number.isFinite(n) && n >= 0 ? n : null;
}


function extractEmails(text) {
  return [...new Set(
    (String(text || "").match(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi
    ) || []).map(x => x.trim().toLowerCase())
  )];
}

function extractPhones(text) {
  const found = [];

  for (const line of String(text || "").split(/\r?\n/)) {
    if (!/(телефон|тел\.|мобильн|phone)/i.test(line)) continue;

    const matches = line.match(/\+?\d[\d\s().-]{6,}\d/g) || [];

    for (const value of matches) {
      const digits = value.replace(/\D/g, "");
      if (digits.length >= 10 && digits.length <= 15) {
        found.push(value.replace(/\s+/g, " ").trim());
      }
    }
  }

  const unique = new Map();
  for (const phone of found) {
    const key = phone.replace(/\D/g, "");
    if (!unique.has(key)) unique.set(key, phone);
  }

  return [...unique.values()];
}

function extractInn(text) {
  for (const line of String(text || "").split(/\r?\n/)) {
    const rawLabel = (line.split(/[:：]/, 1)[0] || "")
      .toUpperCase()
      .replace(/[^A-ZА-ЯЁ]/g, "");

    const label = rawLabel
      .replace(/[UI]/g, "И")
      .replace(/H/g, "Н");

    if (!label.includes("ИНН")) continue;

    const candidates = line.match(/\d[\d\s-]{8,16}\d/g) || [];

    for (const candidate of candidates) {
      const digits = candidate.replace(/\D/g, "");
      if (digits.length === 10 || digits.length === 12) {
        return digits;
      }
    }
  }

  return null;
}

const records = [];

for (let i = 0; i < outputs.length; i++) {
  let content = outputs[i].json?.message?.content;

  if (typeof content !== "string") {
    throw new Error("Нет message.content у Ollama, страница " + (i + 1));
  }

  content = content.trim();

  const fence = String.fromCharCode(96).repeat(3);

  if (content.startsWith(fence)) {
    content = content.replace(
      new RegExp("^" + fence + "(?:json)?\\s*", "i"), ""
    );
    content = content.replace(
      new RegExp("\\s*" + fence + "$"), ""
    );
  }

  let parsed;

  try {
    parsed = JSON.parse(content);
  } catch (e) {
    throw new Error("Ошибка JSON Ollama на странице " + (i + 1));
  }

  if (!Array.isArray(parsed.records)) {
    throw new Error("Нет массива records на странице " + (i + 1));
  }

  const page = pages[i].json;

  for (let j = 0; j < parsed.records.length; j++) {
    const r = parsed.records[j] || {};
    const row = j + 1;

    const warnings = Array.isArray(r.warnings)
      ? r.warnings.map(String)
      : [];

    const emails = Array.isArray(r.emails)
      ? r.emails.filter(Boolean)
      : [];

    const phones = Array.isArray(r.phones)
      ? r.phones.filter(Boolean)
      : [];

    if (r.email) emails.push(r.email);
    if (r.phone) phones.push(r.phone);

    const pageText = String(page.page_text || "");
    const ocrEmailCandidates = extractEmails(pageText);
    const ocrPhoneCandidates = extractPhones(pageText);
    const ocrInn = extractInn(pageText);

    const modelEmailSet = new Set(
      emails.map(x => String(x).trim().toLowerCase())
    );

    const unconfirmedEmails = ocrEmailCandidates.filter(
      x => !modelEmailSet.has(x)
    );

    const modelPhoneSet = new Set(
      phones.map(x => String(x).replace(/\D/g, ""))
    );

    const unconfirmedPhones = ocrPhoneCandidates.filter(
      x => !modelPhoneSet.has(x.replace(/\D/g, ""))
    );

    if (unconfirmedEmails.length) {
      warnings.push(
        "ocr_contains_unconfirmed_email_candidates:" +
        unconfirmedEmails.length
      );
    }

    if (unconfirmedPhones.length) {
      warnings.push(
        "ocr_contains_unconfirmed_phone_candidates:" +
        unconfirmedPhones.length
      );
    }

    const modelInnDigits = r.inn
      ? String(r.inn).replace(/\D/g, "")
      : "";

    const validModelInn = [10, 12].includes(modelInnDigits.length)
      ? modelInnDigits
      : null;

    const finalInn = validModelInn || (parsed.records.length === 1 ? ocrInn : null);

    if (!validModelInn && finalInn) {
      warnings.push("inn_recovered_from_ocr_labeled_line");
    }

    if (r.city && /[A-Za-z]/.test(String(r.city))) {
      warnings.push("city_contains_latin_characters_check_source_pdf");
    }

    if (page.needs_review) {
      warnings.push("ocr_page_requires_review");
    }

    records.push({
      ...r,
      inn: finalInn,
      email: r.email || emails[0] || null,
      phone: r.phone || phones[0] || null,
      emails: [...new Set(
        emails.map(x => String(x).trim()).filter(Boolean)
      )],
      phones: [...new Set(
        phones.map(x => String(x).trim()).filter(Boolean)
      )],
      revenue_rub: normalizeRevenue(r.revenue_rub),
      source_page: page.source_page,
      source_row: row,
      source_row_model: r.source_row || null,
      source_key: "p" + page.source_page + "-r" + row,
      source_locator: "page=" + page.source_page + ";row=" + row,
      extraction_warnings: [...new Set(warnings)]
    });
  }
}

if (!records.length) {
  throw new Error("Ollama не обнаружил ни одной записи компаний или инвесторов");
}

return [{ json: { records } }];

const items = $input.all();

if (!items.length) {
  throw new Error("Excel не содержит строк данных");
}

function norm(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/ё/g, "е")
    .replace(/[^0-9a-zа-я]/g, "");
}

function findEntry(row, aliases) {
  const wanted = new Set(aliases.map(norm));

  for (const [key, value] of Object.entries(row)) {
    if (
      wanted.has(norm(key)) &&
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ""
    ) {
      return { key, value };
    }
  }

  return null;
}

function pick(row, aliases) {
  return findEntry(row, aliases)?.value ?? null;
}

function parseNumber(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") {
    return Number.isFinite(value) && value >= 0 ? value : null;
  }

  let s = String(value)
    .replace(/\u00a0/g, " ")
    .replace(/руб\.?|₽/gi, "")
    .replace(/\s/g, "")
    .trim();

  if (s.includes(",") && s.includes(".")) {
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) {
      s = s.replace(/\./g, "").replace(",", ".");
    } else {
      s = s.replace(/,/g, "");
    }
  } else if (s.includes(",")) {
    const a = s.split(",");
    s = a.length === 2 && a[1].length !== 3
      ? s.replace(",", ".")
      : s.replace(/,/g, "");
  }

  const n = Number(s);
  return Number.isFinite(n) && n >= 0 ? n : null;
}

const records = items.map((item, index) => {
  const row = item.json || {};
  const warnings = [];

  const company = pick(row, [
    "company_name", "company", "organization", "legal_name",
    "counterparty_name", "наименование организации",
    "наименование компании", "название организации",
    "название компании", "организация", "компания",
    "контрагент", "инвестор", "эмитент"
  ]);

  const innRaw = pick(row, ["inn", "инн", "tax id"]);
  const innDigits = innRaw === null
    ? ""
    : String(innRaw).replace(/\D/g, "");

  const inn = [10, 12].includes(innDigits.length) ? innDigits : null;

  if (innRaw && !inn) warnings.push("inn_requires_review");

  const fullName = pick(row, [
    "full_name", "contact_person", "person_name", "fio",
    "фио", "фио контакта", "контактное фио",
    "контактное лицо", "имя контакта"
  ]);

  const position = pick(row, [
    "position", "job_title", "title", "должность",
    "должность контакта", "позиция"
  ]);

  const city = pick(row, [
    "city", "location", "город", "регион", "местоположение"
  ]);

  const email = pick(row, [
    "email", "emails", "e-mail", "mail", "почта",
    "электронная почта", "адрес электронной почты"
  ]);

  const phone = pick(row, [
    "phone", "phones", "telephone", "mobile",
    "телефон", "телефоны", "мобильный телефон",
    "контактный телефон", "рабочий телефон"
  ]);

  const revenueEntry = findEntry(row, [
    "revenue_rub", "annual_revenue_rub", "revenue",
    "annual revenue", "выручка", "годовая выручка",
    "выручка за год", "оборот",
    "выручка млн руб", "годовая выручка млн руб",
    "выручка тыс руб", "выручка млрд руб"
  ]);

  let revenueValue = revenueEntry
    ? parseNumber(revenueEntry.value)
    : null;

  const revenueKey = revenueEntry ? norm(revenueEntry.key) : "";

  let multiplier = 1;

  if (/млрд|billion/.test(revenueKey)) multiplier = 1000000000;
  else if (/млн|million/.test(revenueKey)) multiplier = 1000000;
  else if (/тыс|thousand/.test(revenueKey)) multiplier = 1000;

  if (revenueValue !== null) {
    revenueValue *= multiplier;
  }

  if (revenueEntry && revenueValue === null) {
    warnings.push("revenue_requires_review");
  }

  const yearRaw = pick(row, [
    "revenue_year", "год выручки", "отчетный год",
    "отчётный год", "годовой отчет"
  ]);

  const year = yearRaw === null
    ? null
    : Number.parseInt(yearRaw, 10);

  const revenueYear =
    Number.isInteger(year) && year >= 1900 && year <= 2100
      ? year
      : null;

  if (yearRaw !== null && revenueYear === null) {
    warnings.push("revenue_year_requires_review");
  }

  return {
    ...row,
    company_name: company === null ? null : String(company).trim(),
    inn,
    city: city === null ? null : String(city).trim(),
    full_name: fullName === null ? null : String(fullName).trim(),
    position: position === null ? null : String(position).trim(),
    email: email === null ? null : String(email).trim(),
    phone: phone === null ? null : String(phone).trim(),
    revenue_rub: revenueValue,
    revenue_year: revenueYear,
    revenue_source: revenueEntry ? "document" : null,
    source_row: index + 2,
    source_key: "row-" + (index + 2),
    source_locator: "row=" + (index + 2),
    extraction_warnings: warnings
  };
});

return records.map(json => ({ json }));

const records = $input.all().map(x => x.json);

if (!records.length) {
  throw new Error("Нет строк Excel для записи в CRM");
}

return [{ json: { records } }];

const ext = $("Claim and normalize").first().json.file_extension;

return [{
  json: {
    error: "Формат ." + ext +
      " пока не поддерживается. Доступны PDF, XLS, XLSX, DOC и DOCX."
  }
}];
